// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    // Accept ETH so the owner's `transfer` inside `withdraw` succeeds on the reference.
    receive() external payable {}

    function testFuzz_property(uint256 amount) public {
        // Admissible domain: any positive amount the contract could be funded with.
        amount = bound(amount, 1, type(uint128).max);

        // Fund the contract through its payable fallback.
        vm.deal(address(this), amount);
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "deposit failed");

        // Owner (setUp's deployer, i.e. this test contract) drains everything.
        c.withdrawAll();

        // The reference always fully drains; the mutant leaves the balance untouched.
        assertTrue(address(c).balance == 0);
    }
}
